def page_hero(eyebrow,title,lead,name,art=False,tabs=''):
 content=f'<div><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span><span>{name}</span></nav><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p class="lead">{lead}</p>{tabs}</div>'
